function [y, seen, st] = least(st, x)
%LEAST  The least value seen, from a state that starts at inf.
%   x: real[s] (passed in s)
%   returns y: real[s] (passed in s)
%   returns seen: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    if isempty(st)
        st = struct();
        st.low = Inf;
    end
    y = 0;
    seen = false;
    st.low = asils.pc.fmin(st.low, x);
    seen = isfinite(st.low);
    y = asils.pc.choose(seen, st.low, 0);
end
